function form_value(string $key, string $default = ''): string { return trim((string) ($_POST[$key] ?? $default)); }
function form_number(string $key): float { return (float) str_replace(',', '.', (string) ($_POST[$key] ?? 0)); }
function form_active(): int { return isset($_POST['is_active']) ? 1 : 0; }
function slug_name(string $value): string { $value = strtr(mb_strtolower($value, 'UTF-8'), ['ç'=>'c','ğ'=>'g','ı'=>'i','ö'=>'o','ş'=>'s','ü'=>'u']); return trim((string) preg_replace('/[^a-z0-9]+/', '-', $value), '-') ?: 'pelish-'.date('YmdHis'); }
function auto_product_sku(PDO $pdo): string { do { $sku = 'PLS-' . date('ymd') . '-' . strtoupper(bin2hex(random_bytes(3))); $check = $pdo->prepare('SELECT COUNT(*) FROM pelish_products WHERE sku = ?'); $check->execute([$sku]); } while ((int) $check->fetchColumn() > 0); return $sku; }
function ean13_check_digit(string $firstTwelve): string { $sum = 0; for ($index = 0; $index < 12; $index++) { $sum += (int) $firstTwelve[$index] * ($index % 2 === 0 ? 1 : 3); } return (string) ((10 - ($sum % 10)) % 10); }
function auto_product_barcode(PDO $pdo): string { do { $prefix = '869' . str_pad((string) random_int(0, 999999999), 9, '0', STR_PAD_LEFT); $barcode = $prefix . ean13_check_digit($prefix); $check = $pdo->prepare('SELECT COUNT(*) FROM pelish_products WHERE barcode = ?'); $check->execute([$barcode]); } while ((int) $check->fetchColumn() > 0); return $barcode; }
function selected_product_category(PDO $pdo): string { $category = form_value('category'); if ($category !== '__new__') { return $category ?: 'Genel'; } $newCategory = form_value('new_category'); if ($newCategory === '') { throw new RuntimeException('Yeni kategori adı zorunludur.'); } $statement = $pdo->prepare('SELECT id FROM pelish_catalog_items WHERE type = "categories" AND name = ? LIMIT 1'); $statement->execute([$newCategory]); if (!$statement->fetchColumn()) { $pdo->prepare('INSERT INTO pelish_catalog_items (type, name, slug, description, is_active) VALUES ("categories", ?, ?, NULL, 1)')->execute([$newCategory, slug_name($newCategory)]); } return $newCategory; }
function image_upload_requested(): bool { foreach (($_FILES['product_images']['error'] ?? []) as $error) { if ($error !== UPLOAD_ERR_NO_FILE) { return true; } } return false; }
function upload_product_images(PDO $pdo, array $r2Settings, int $productId, string $productName, array $files, array $colorNames, array $colorHexes, int $primaryIndex): int { $uploads = []; foreach (($files['name'] ?? []) as $index => $name) { $error = $files['error'][$index] ?? UPLOAD_ERR_NO_FILE; if ($error === UPLOAD_ERR_NO_FILE) { continue; } $hex = trim((string) ($colorHexes[$index] ?? '')); if ($hex !== '' && !preg_match('/^#[0-9A-Fa-f]{6}$/', $hex)) { throw new RuntimeException('Renk kodu #RRGGBB biçiminde olmalıdır.'); } $uploads[] = ['source_index' => (int) $index, 'file' => ['name' => $name, 'type' => $files['type'][$index] ?? '', 'tmp_name' => $files['tmp_name'][$index] ?? '', 'error' => $error, 'size' => $files['size'][$index] ?? 0], 'color_name' => trim((string) ($colorNames[$index] ?? '')) ?: null, 'color_hex' => $hex ?: null]; }
    if (!$uploads) { return 0; } $primaryCheck = $pdo->prepare('SELECT COUNT(*) FROM pelish_product_images WHERE product_id = ? AND is_primary = 1'); $primaryCheck->execute([$productId]); $primaryExists = (int) $primaryCheck->fetchColumn() > 0; $requestedPrimaryFound = false; foreach ($uploads as $upload) { if ($upload['source_index'] === $primaryIndex) { $requestedPrimaryFound = true; break; } } $uploaded = 0; foreach ($uploads as $upload) { $asset = r2_upload_image($r2Settings, $upload['file'], $productName); $isPrimary = ($requestedPrimaryFound && $upload['source_index'] === $primaryIndex) || (!$primaryExists && !$requestedPrimaryFound && $uploaded === 0); if ($isPrimary) { $pdo->prepare('UPDATE pelish_product_images SET is_primary = 0 WHERE product_id = ?')->execute([$productId]); } $orderStatement = $pdo->prepare('SELECT COALESCE(MAX(sort_order), 0) + 1 FROM pelish_product_images WHERE product_id = ?'); $orderStatement->execute([$productId]); $order = (int) $orderStatement->fetchColumn(); $pdo->prepare('INSERT INTO pelish_product_images (product_id, image_url, image_key, color_name, color_hex, sort_order, is_primary) VALUES (?, ?, ?, ?, ?, ?, ?)')->execute([$productId, $asset['url'], $asset['key'], $upload['color_name'], $upload['color_hex'], $order, $isPrimary ? 1 : 0]); if ($isPrimary) { $pdo->prepare('UPDATE pelish_products SET image_url = ?, image_key = ? WHERE id = ?')->execute([$asset['url'], $asset['key'], $productId]); $primaryExists = true; } $uploaded++; } return $uploaded; }
function redirect_page(string $page, array $query = []): never { header('Location: '.admin_url($page, $query)); exit; }
function option_list(array $values, string $selected = ''): void { foreach ($values as $key => $value) { $optionValue = is_string($key) ? $key : (string) $value; ?><option value="<?= e($optionValue) ?>" <?= $optionValue === $selected ? 'selected' : '' ?>><?= e((string) $value) ?></option><?php } }
function confirm_button(string $action, int $id, string $message, array $extra = []): void { ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="<?=e($action)?>"><input type="hidden" name="id" value="<?=$id?>"><?php foreach($extra as $name=>$value):?><input type="hidden" name="<?=e($name)?>" value="<?=e((string)$value)?>"><?php endforeach?><button class="danger-button" data-confirm="<?=e($message)?>" title="Sil"><i class="fa-solid fa-trash"></i></button></form><?php }
function modal(string $page, string $label, string $title, string $content): void { ?>
  <div class="modal <?= (isset($_GET['new']) || isset($_GET['edit'])) ? 'is-open' : '' ?>"><div class="modal-dialog"><div class="modal-head"><div><span><?=e($label)?></span><h2><?=e($title)?></h2></div><a class="modal-close" href="<?=admin_url($page)?>">×</a></div><?=$content?></div></div>
