        $data=['name'=>form_value('name'),'category'=>'Genel','sku'=>$existingImage['sku']??auto_product_sku($pdo),'barcode'=>$existingImage['barcode']??auto_product_barcode($pdo),'image_url'=>$existingImage['image_url']??null,'image_key'=>$existingImage['image_key']??null,'sale_price'=>form_number('sale_price'),'list_price'=>form_number('list_price'),'cost_price'=>form_number('cost_price'),'stock'=>max(0,(int)($_POST['stock']??0)),'desi'=>$existingImage['desi']??0,'is_active'=>form_active()];
