    if ($action === 'save-customer') {
        $id=(int)($_POST['id']??0);$data=['first_name'=>form_value('first_name'),'last_name'=>form_value('last_name'),'email'=>form_value('email'),'phone'=>form_value('phone')?:null,'city'=>form_value('city')?:null,'district'=>form_value('district')?:null,'is_active'=>form_active()];
        if($data['first_name']===''||$data['last_name']===''||!filter_var($data['email'],FILTER_VALIDATE_EMAIL)){admin_flash('danger','Ad, soyad ve geçerli e-posta zorunludur.');redirect_page('customers',['new'=>1]);}
        try{if($id){$data['id']=$id;$pdo->prepare('UPDATE pelish_customers SET first_name=:first_name,last_name=:last_name,email=:email,phone=:phone,city=:city,district=:district,is_active=:is_active WHERE id=:id')->execute($data);}else{$pdo->prepare('INSERT INTO pelish_customers (first_name,last_name,email,phone,city,district,is_active) VALUES (:first_name,:last_name,:email,:phone,:city,:district,:is_active)')->execute($data);}admin_flash('success',$id?'Müşteri güncellendi.':'Yeni müşteri eklendi.');}catch(PDOException $e){admin_flash('danger','Bu e-posta zaten kullanılıyor.');}redirect_page('customers');
    }
