function dashboard(PDO $pdo): void {
  $m=$pdo->query("SELECT (SELECT COUNT(*) FROM pelish_products WHERE is_active=1) products,(SELECT COUNT(*) FROM pelish_orders WHERE DATE(created_at)=CURDATE()) orders,(SELECT COALESCE(SUM(grand_total),0) FROM pelish_orders WHERE DATE(created_at)=CURDATE() AND status<>'İptal') revenue,(SELECT COUNT(*) FROM pelish_customers WHERE password_hash IS NOT NULL) customers,(SELECT COUNT(DISTINCT c.customer_id) FROM pelish_customer_carts c INNER JOIN pelish_customer_cart_items i ON i.cart_id=c.id) cart_customers,(SELECT COUNT(*) FROM pelish_customer_favorites) favorites")->fetch();$recent=$pdo->query('SELECT o.*,CONCAT(c.first_name," ",c.last_name) customer FROM pelish_orders o LEFT JOIN pelish_customers c ON c.id=o.customer_id ORDER BY o.id DESC LIMIT 6')->fetchAll();$low=$pdo->query('SELECT * FROM pelish_products WHERE stock<=5 ORDER BY stock LIMIT 6')->fetchAll();$popular=$pdo->query('SELECT p.id,p.name,COUNT(f.id) favorite_count FROM pelish_products p LEFT JOIN pelish_customer_favorites f ON f.product_id=p.id GROUP BY p.id ORDER BY favorite_count DESC,p.name LIMIT 5')->fetchAll();
  panel_header('dashboard','Ana Sayfa',[['label'=>'Genel Bakış','href'=>admin_url('dashboard'),'active'=>true],['label'=>'Hızlı İşlemler','href'=>'#quick']]);?>
