function products(PDO $pdo, array $r2Settings): void {
  $q=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'all');$where=[];$args=[];if($q!==''){$where[]='(name LIKE ? OR sku LIKE ? OR barcode LIKE ? OR category LIKE ?)';$args=array_fill(0,4,'%'.$q.'%');}if($status==='active')$where[]='is_active=1';if($status==='passive')$where[]='is_active=0';if($status==='stock')$where[]='stock>0';if($status==='out-of-stock')$where[]='stock=0';$st=$pdo->prepare('SELECT p.*, (SELECT COUNT(*) FROM pelish_customer_favorites f WHERE f.product_id=p.id) favorite_count FROM pelish_products p'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY p.id DESC');$st->execute($args);$items=$st->fetchAll();$m=$pdo->query('SELECT COUNT(*) total,SUM(is_active=1) active,COALESCE(SUM(stock),0) stock,SUM(stock=0) empty_stock FROM pelish_products')->fetch();$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM pelish_products WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch()?:null;}$f=$edit?:['id'=>'','name'=>'','category'=>'','sku'=>'','barcode'=>'','image_url'=>'','image_key'=>'','sale_price'=>'','list_price'=>'','cost_price'=>'','stock'=>0,'desi'=>0,'is_active'=>1];$categories=$pdo->query('SELECT name FROM pelish_catalog_items WHERE type="categories" AND is_active=1 UNION SELECT DISTINCT category AS name FROM pelish_products ORDER BY name')->fetchAll(PDO::FETCH_COLUMN);$images=[];if($edit){$imageQuery=$pdo->prepare('SELECT * FROM pelish_product_images WHERE product_id=? ORDER BY is_primary DESC,sort_order,id');$imageQuery->execute([$edit['id']]);$images=$imageQuery->fetchAll();}
  panel_header('products','Ürün Yönetimi',[['label'=>'Ürünler','href'=>admin_url('products'),'active'=>true],['label'=>'Kategoriler','href'=>admin_url('catalog',['type'=>'categories'])],['label'=>'Markalar','href'=>admin_url('catalog',['type'=>'brands'])],['label'=>'Etiketler','href'=>admin_url('catalog',['type'=>'tags'])]]);?>
  <section class="stat-grid"><article><span>TOPLAM ÜRÜN</span><strong><?= (int)$m['total']?></strong><i class="fa-solid fa-boxes-stacked"></i></article><article><span>AKTİF ÜRÜN</span><strong><?= (int)$m['active']?></strong><i class="fa-solid fa-circle-check"></i></article><article><span>TOPLAM STOK</span><strong><?= (int)$m['stock']?></strong><i class="fa-solid fa-cubes"></i></article><article><span>STOKTA YOK</span><strong><?= (int)$m['empty_stock']?></strong><i class="fa-solid fa-triangle-exclamation"></i></article></section>
