  <section class="table-card"><div class="table-title"><div><span>ÜRÜNLER</span><h1>Ürün listesi</h1></div><a class="button primary" href="<?=admin_url('products',['new'=>1])?>"><i class="fa-solid fa-plus"></i> Yeni Ürün</a></div><div class="table-scroll"><table><thead><tr><th>No</th><th>Resim</th><th>Ürün Bilgileri</th><th>Site</th><th>Favori</th><th>Stok</th><th>İşlemler</th></tr></thead><tbody><?php foreach($items as $p):?><tr><td><a class="product-no" href="<?=admin_url('products',['edit'=>$p['id']])?>">#<?= (int)$p['id']?></a></td><td><a class="product-image" href="<?=admin_url('products',['edit'=>$p['id']])?>"><img src="<?=e($p['image_url']?:'https://cdn.pelish.co/logo.png')?>" alt="<?=e($p['name'])?>"></a></td><td class="product-info"><a href="<?=admin_url('products',['edit'=>$p['id']])?>"><strong><?=e($p['name'])?></strong></a><span>Kategori: <b><?=e($p['category'])?></b></span><span>Kodu: <b><?=e($p['sku'])?></b></span><span>Barkod: <b><?=e($p['barcode']?:'-')?></b></span></td><td class="price-cell"><form method="post" class="status-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle-product"><input type="hidden" name="id" value="<?= (int)$p['id']?>"><button class="status <?=$p['is_active']?'on':''?>"><i class="fa-regular fa-circle-check"></i></button></form><strong><?=admin_money((float)$p['sale_price'])?></strong><span>P: <?=admin_money((float)$p['list_price'])?></span></td><td><strong><i class="fa-solid fa-heart"></i> <?= (int)$p['favorite_count']?></strong></td><td><strong class="stock <?=!$p['stock']?'empty':''?>"><?= (int)$p['stock']?></strong></td><td><div class="row-actions"><a href="<?=admin_url('products',['edit'=>$p['id']])?>"><i class="fa-solid fa-pen"></i></a><a href="../urun.php?id=<?= (int)$p['id']?>" target="_blank"><i class="fa-solid fa-arrow-up-right-from-square"></i></a><?php confirm_button('delete-product',(int)$p['id'],'Bu ürün kalıcı olarak silinsin mi?')?></div></td></tr