mers',['edit'=>$i['id']])?>"><i class="fa-solid fa-pen"></i></a><?php confirm_button('delete-customer',(int)$i['id'],'Bu müşteri silinsin mi?')?></div></td></tr><?php endforeach?></tbody></table></div></section>
