function customer_carts(PDO $pdo): void {
  $items=$pdo->query('SELECT c.id customer_id,c.first_name,c.last_name,c.email,c.phone,cart.updated_at,GROUP_CONCAT(CONCAT(p.name,IF(i.selected_size IS NULL,"",CONCAT(" · ",i.selected_size)),IF(i.color_name IS NULL,"",CONCAT(" · ",i.color_name))," ×",i.quantity) ORDER BY i.id SEPARATOR "||") products,SUM(i.quantity) item_count,SUM(i.quantity*p.sale_price) cart_total FROM pelish_customer_carts cart INNER JOIN pelish_customer_cart_items i ON i.cart_id=cart.id INNER JOIN pelish_customers c ON c.id=cart.customer_id INNER JOIN pelish_products p ON p.id=i.product_id GROUP BY cart.id,c.id ORDER BY cart.updated_at DESC')->fetchAll();
  panel_header('customers','Sepetinde Ürün Olanlar',[['label'=>'Müşteri Listesi','href'=>admin_url('customers')],['label'=>'Sepetinde Ürün Olanlar','href'=>admin_url('customers',['view'=>'carts']),'active'=>true]]);?>
  <section class="licence-card"><div class="licence-icon"><i class="fa-solid fa-cart-shopping"></i></div><div><strong>Satın almaya yakın müşteriler.</strong><p>Bu liste, hesabında ürün bırakan müşterilerin canlı sepetlerini gösterir. Ödeme tamamlandığında sepet ayrıca yönetilebilir.</p></div></section><section class="table-card"><div class="table-title"><div><span>MÜŞTERİ NİYETİ</span><h1>Sepetinde ürün olanlar</h1></div><a class="button ghost" href="<?=admin_url('customers')?>">Müşteriler</a></div><div class="table-scroll"><table><thead><tr><th>Müşteri</th><th>İletişim</th><th>Sepetteki ürünler</th><th>Adet</th><th>Sepet tutarı</th><th>Son hareket</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><strong><?=e($item['first_name'].' '.$item['last_name'])?></strong><br><span class="cell-muted">#<?= (int)$item['customer_id']?></span></td><td><?=e($item['email'])?><br><span class="cell-muted"><?=e($item['phone']?:'-')?></span></td><td><?php foreach(explode('||',(string)$item['products']) as $product):?><span class="cart-product-line"><?=e($product)?></span><?php endforeach?></td><td><strong><?= (int)$item['item_count']?></strong></td><td><strong><?=admin_money((float)$item['cart_total'])?></strong></td><td><?=date('d.m.Y H:i',strtotime($item['updated_at']))?></td></tr><?php endforeach;if(!$items):?><tr><td colspan="6" class="empty-table"><i class="fa-solid fa-cart-shopping"></i><strong>Henüz ürün eklenmiş sepet yok.</strong></td></tr><?php endif?></tbody></table></div></section><?php panel_footer();
}

